sys_script_include.script:
var CreateEventProcessor = Class.create();
CreateEventProcessor.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

  createEventRecord: function() {
    try {
      // Get parameters from the client-side GlideAjax call
      var eventName = this.getParameter('sysparm_event_name');
      var eventDate = this.getParameter('sysparm_event_date');
      var location = this.getParameter('sysparm_location');
      var contactPerson = this.getParameter('sysparm_contact_person');
      var contactNumber = this.getParameter('sysparm_contact_number');
      var email = this.getParameter('sysparm_email');
      var status = this.getParameter('sysparm_status');

      var gr = new GlideRecord('x_1790233_event_ma_event_record');
      gr.initialize();
      gr.setValue('event_name', eventName);
      gr.setValue('event_date', eventDate);
      gr.setValue('location', location);
      gr.setValue('contact_person', contactPerson);
      gr.setValue('contact_number', contactNumber);
      gr.setValue('email', email);
      gr.setValue('u_event_state', status); 

      var sys_id = gr.insert();

      if (sys_id) {
        return "success";
      } else {
        return "fail";
      }

    } catch (e) {
      // Log error for server logs
      gs.error("CreateEventProcessor Error: " + e.message);
      return "error: " + e.message;
    }
  },

  type: 'CreateEventProcessor'
});
